create extension if not exists "pgcrypto";
create table if not exists users(id uuid primary key default gen_random_uuid(),name text not null,email text unique not null,password_hash text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,title text not null,genre text not null,language text not null default 'Hindi',description text,status text not null default 'draft',episode_count int not null default 9,scene_duration int not null default 10,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists characters(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,name text not null,age int,gender text,description text,personality text,visual_dna jsonb not null default '{}'::jsonb,backstory text,identity_lock boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists episodes(id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,episode_number int not null,title text not null,logline text,synopsis text,story text,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(project_id,episode_number));
create table if not exists scenes(id uuid primary key default gen_random_uuid(),episode_id uuid not null references episodes(id) on delete cascade,scene_number int not null,duration int not null default 10,description text,image_prompt text,video_prompt text,voiceover text,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(episode_id,scene_number));
create table if not exists scene_assets(id uuid primary key default gen_random_uuid(),scene_id uuid not null references scenes(id) on delete cascade,type text not null,provider text,url text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists generation_jobs(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete set null,project_id uuid references projects(id) on delete cascade,scene_id uuid references scenes(id) on delete cascade,job_type text not null,provider text,status text not null default 'queued',input jsonb not null default '{}'::jsonb,output jsonb,error text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists usage_logs(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete set null,provider text,operation text,units numeric,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
